draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // sun
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W/2, H/4, 30, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // millet
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20 + 10 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // stick figure farmer
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 50, H - 50, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H - 40);
  ctx.lineTo(W/2 - 50, H - 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H - 30);
  ctx.lineTo(W/2 - 70, H - 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H - 30);
  ctx.lineTo(W/2 - 30, H - 20);
  ctx.stroke();

  // drought resistant text
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Drought Resistant', W/2, H - 100 + 20 * Math.sin(t));

  ctx.restore();
}
